import org.apache.commons.lang3.builder.EqualsBuilder

class BadEquals(private val id: String) {
    override fun equals(other: Any?): Boolean {
        return EqualsBuilder.reflectionEquals(this, other)
    }
}

import org.apache.commons.lang3.builder.HashCodeBuilder

class BadHash(private val id: String) {
    override fun hashCode(): Int {
        return HashCodeBuilder.reflectionHashCode(this)
    }
}

class GoodManual(private val id: String) {
    override fun equals(other: Any?): Boolean {
        return other is GoodManual && id == other.id
    }

    override fun hashCode(): Int {
        return id.hashCode()
    }
}

import org.apache.commons.lang3.builder.EqualsBuilder

class GoodAppend(private val field1: String) {
    fun sameAs(other: GoodAppend): Boolean {
        return EqualsBuilder().append(field1, other.field1).isEquals
    }
}
